--
-- TOC entry 266 (class 1255 OID 16404)
-- Name: func_lay_ten(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.func_lay_ten(p_ido character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
	declare 
		rec record;
		code text;
		p_id int;
	
	begin
		code := substring(p_ido,1,3);
		p_id := substring(p_ido, 4)::int;
		if code = 'GRP' then
			select into rec ten from tbl_nhomdoituong where id = p_id;
		elsif code = 'CLS' then
			select into rec ten from tbl_loaidoituong where id = p_id;
		elsif code = 'TYP' then
			select into rec ten from tbl_kieudoituong where id = p_id;
		else
			select into rec ten from tbl_doituong where id = p_id;
		end if;
	return rec.ten;
	end
$$;


ALTER FUNCTION public.func_lay_ten(p_ido character varying) OWNER TO postgres;

--
-- TOC entry 267 (class 1255 OID 16405)
-- Name: func_lay_tennhom_idt(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.func_lay_tennhom_idt(p_idophanloai character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
	declare
		rec record;
		code text;
		idn int;
	begin
		code := substring(p_idophanloai, 1, 3);
		idn := substring(p_idophanloai, 4);
		if code = 'TYP' then
			select into rec tbl_nhomdoituong.ten
			from tbl_kieudoituong, tbl_loaidoituong, tbl_nhomdoituong
			where tbl_kieudoituong.id_loai = tbl_loaidoituong.id
					and tbl_loaidoituong.id_nhom = tbl_nhomdoituong.id
					and tbl_kieudoituong.id = idn;
		else
			select into rec tbl_nhomdoituong.ten
			from tbl_nhomdoituong
			where tbl_nhomdoituong.id = idn;
		end if;
		return rec.ten;
	end
$$;


ALTER FUNCTION public.func_lay_tennhom_idt(p_idophanloai character varying) OWNER TO postgres;

