CREATE FUNCTION public.func_layid_doituong(p_tendoituong text, p_idophanloai character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
	declare iddoituong int;
	begin
		iddoituong := (select tbl_doituong.id
						from tbl_doituong
						where lower(tbl_doituong.ten)=lower(p_tendoituong)
							and ido_phanloai = p_idophanloai);
		if iddoituong is null then
			iddoituong := -1;
		end if;
		return iddoituong;
	end
$$;


