--
-- TOC entry 279 (class 1255 OID 16423)
-- Name: func_sua_doituong(integer, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.func_sua_doituong(p_id integer, p_tendoituong text, p_idophanloai character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
	begin
		if func_layid_doituong(p_tendoituong, p_idophanloai) = -1 then
			update tbl_doituong
			set ten = p_tendoituong,
				ido_phanloai = p_idophanloai
			where id = p_id;
			return true;
		end if;
		return false;
	end
$$;


