--

CREATE FUNCTION public.func_them_taikhoan(character varying, character varying, integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
	declare idtaikhoan int;
	begin
		idtaikhoan := (select func_layid_taikhoan($1));
		if idtaikhoan <> -1 then
			return false;
		end if;
		insert into tbl_taikhoan(tendangnhap, matkhau, quyen) values($1,$2,$3);
		return true;
	end
$_$;


