-- Name: func_xoa_nhomdoituong(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.func_xoa_nhomdoituong(p_tennhom text) RETURNS void
    LANGUAGE plpgsql
    AS $$
	begin
		delete from tbl_nhomdoituong
			where lower(ten) = lower(p_tennhom);
	end
$$;


ALTER FUNCTION public.func_xoa_nhomdoituong(p_tennhom text) OWNER TO postgres;

--
-- TOC entry 315 (class 1255 OID 16459)
-- Name: func_xoa_taikhoan(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.func_xoa_taikhoan(character varying) RETURNS void
    LANGUAGE plpgsql
    AS $_$
	begin
		delete from tbl_taikhoan where tendangnhap=$1;
	end
$_$;


ALTER FUNCTION public.func_xoa_taikhoan(character varying) OWNER TO postgres;

